<script>
document.addEventListener("DOMContentLoaded", function() {
  const popupData = {
    imageUrl: "{{ asset('/images/home/' . $popup->pu_img ) }}",
    redirectUrl: "{{ $popup->pu_url }}"
  };

  const popupImage = document.getElementById("popupImage");
  const popupLink = document.getElementById("popupLink");
  popupImage.src = popupData.imageUrl;
  popupLink.href = popupData.redirectUrl;

  const popupOverlay = document.getElementById("popupOverlay");
  popupOverlay.classList.add("active");

  popupOverlay.addEventListener("click", function(event) {
    if (event.target === popupOverlay) {
        popupOverlay.classList.remove("active");
    }
  });
});

const rotatingImage = document.getElementById('rotatingImage');

const images = [
    @foreach ($explodedImg as $img)
        "{{ asset('/images/home/' . $img) }}",
    @endforeach
];

let currentIndex = 0;

function rotateImages() {
    rotatingImage.style.opacity = 0.1;
    setTimeout(() => {
        currentIndex = (currentIndex + 1) % images.length;
        rotatingImage.src = images[currentIndex];
        rotatingImage.style.opacity = 1; 
    }, 700); 

}

setInterval(rotateImages, 7000);

// $('.marquee').marquee({
//   direction: 'left',
//   duplicated: true,
//   duration: 40000,
// })
marqueeInit({
	uniqueid: 'mycrawler',
	inc: 1, //speed - pixel increment for each iteration of this marquee's movement
	mouse: 'false', //mouseover behavior ('pause' 'cursor driven' or false)
	moveatleast: 2,
	neutral: 150,
	savedirection: true,
	random: true
});

marqueeInit({
	uniqueid: 'mycrawlerReview',
